@r1 w.request.request act=change mood=do words="set the chart upside down" predicate=set
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context family_words=chart
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.orientation value="upside down" operator=eq phase=result open_value=true
@r2 w.request.request act=change mood=do words="try the colour purple" predicate=try
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=context
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=chart.colour value=purple operator=eq phase=result key_words=colour
@f3 w.request.filler text="that's the tweak"

@f1 w.request.filler text=also
@f2 w.request.filler text=then
@r1 w.request.request act=change mood=do words="keep the chart upside down" predicate=keep
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context family_words=chart
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.orientation value="upside down" operator=eq phase=result open_value=true
@r2 w.request.request act=change mood=do words="go for colour purple on the profit chart" predicate=go
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=written family_words=chart name="profit chart"
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=chart.colour value=purple operator=eq phase=result key_words=colour

@f1 w.request.filler text=please
@r1 w.request.request act=change mood=do predicate=needs
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=written name="revenue trend"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.orientation value=same words="the same upside down" operator=eq phase=result open_value=true
@r1.s1 w.request.constraint request=$r1 on=attribute attribute=series.label value="Monthly profit" operator=eq phase=selector
